import { Agent, getAgentByName, routeAgentRequest } from 'agents';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }
}

export class Report extends Agent {
  initialState = { topic: null, report: null, generatedAt: null };

  async generate(topic) {
    const report = `Report on ${topic}: (placeholder)`;
    this.setState({ topic, report, generatedAt: new Date().toISOString() });
    return report;
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/reports' && request.method === 'POST') {
      let body;
      try {
        body = await request.json();
      } catch {
        return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
      }
      const topic = body?.topic;
      if (typeof topic !== 'string' || topic.trim() === '') {
        return Response.json({ error: '`topic` must be a non-empty string' }, { status: 400 });
      }

      // A fresh unique name per POST gives a new, separate Report instance.
      // The name (not the raw Durable Object id) is the handle: reach this
      // instance again later with getAgentByName(env.Report, id).
      const id = crypto.randomUUID();
      const report = await (await getAgentByName(env.Report, id)).generate(topic);
      return Response.json({ id, report });
    }

    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

